-- TASK-0006 Lane A: the published AP Chemistry figures.
--
-- Generated from the pilot's verified catalogue, not retyped. Each figure passed the property
-- tests in scripts/lane-a-pilot/verify.py (462 checks) and the two-reader CED review in
-- ced_check.py, whose five planted controls were all rejected.
--
-- Uses are resolved by NATURAL KEY (subject, kind, title), not by a hardcoded reference_entry_id.
-- Development and Production hold the same chemistry entries under different UUIDs, so an id
-- literal taken from one environment fails the foreign key in the other -- which is exactly how
-- this was caught. Matching on title keeps the migration portable and lets the FK stay strict.
--
-- 1 pilot figure(s) are deliberately NOT seeded, having no published reference entry:
--   chem-mb-catalysis (Maxwell-Boltzmann distribution (catalysis))

begin;

insert into app.figures (
  figure_id, subject_key, family, title, short_title, subtitle, caption, alt,
  x_label, y_label, note, synthetic, values_note, labels, params,
  y_tick_fmt, x_tick_fmt, status, source_note
) values
  ('chem-mb-energy', 'ap_chemistry', 'mb_distribution', 'Maxwell–Boltzmann energy distribution', 'Maxwell-Boltzmann energy distribution', 'Raising the temperature increases the fraction of particles beyond Ea', 'Raising the temperature increases the fraction of particles beyond Ea', 'Two distribution curves of relative number of particles against particle energy. The higher-temperature curve is lower at its peak, broader and shifted right, so a larger shaded area lies beyond the vertical activation-energy marker. Illustrative data.', 'particle energy', 'relative number of particles', 'Area beyond Ea estimates the fraction of collisions with sufficient energy.', true, null, '["Horizontal axis", "Vertical axis", "Distribution curve", "Activation energy marker", "Area beyond the marker", "Curves at different temperatures"]'::jsonb, '{"x_max": 8.0, "series": [{"label": "Lower temperature", "theta": 0.78, "style": "solid"}, {"label": "Higher temperature", "theta": 1.48, "style": "dashed"}], "markers": [{"x": 2.75, "label": "Ea", "caption": "activation energy"}]}'::jsonb, '{:.2f}', null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-energy-profile-single', 'ap_chemistry', 'energy_profile', 'Single-step reaction energy profile', 'Single-step energy profile', 'Reactants, one transition state, products', 'Reactants, one transition state, products', 'Energy plotted along the reaction coordinate. The curve rises from the reactant level to a single transition-state maximum, then falls to a product level below the reactants, so the reaction is exothermic. Illustrative data.', 'reaction coordinate', 'energy', null, true, null, '["Vertical axis", "Horizontal axis", "Reactants", "Transition state", "Products", "Activation energy", "Overall energy change"]'::jsonb, '{"nodes": [{"e": 40, "label": "reactants", "kind": "level"}, {"e": 120, "label": "transition state", "kind": "ts"}, {"e": 15, "label": "products", "kind": "level"}], "arrows": [{"x": 0.6, "from": 0, "to": 1, "label": "Ea (forward)"}, {"x": 1.6, "from": 0, "to": 2, "label": "overall energy change"}]}'::jsonb, null, null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-energy-profile-multistep', 'ap_chemistry', 'energy_profile', 'Multistep reaction energy profile', 'Multistep energy profile', 'Each elementary step contributes its own barrier; the largest sets the rate', 'Each elementary step contributes its own barrier; the largest sets the rate', 'Energy along the reaction coordinate for a two-step mechanism. The curve rises to a first transition state, falls to an intermediate, rises to a lower second transition state, then falls to products below the reactant level, so the overall reaction is exothermic. The first barrier is the larger of the two and sets the rate. Illustrative data.', 'reaction coordinate', 'energy', null, true, null, '["Reaction coordinate axis", "Transition state for each step", "Activation energy for each step", "Reaction intermediate(s)", "Overall energy change"]'::jsonb, '{"nodes": [{"e": 30, "label": "reactants", "kind": "level"}, {"e": 130, "label": "transition state 1", "kind": "ts"}, {"e": 70, "label": "intermediate", "kind": "level"}, {"e": 105, "label": "transition state 2", "kind": "ts"}, {"e": 20, "label": "products", "kind": "level"}], "arrows": [{"x": 0.55, "from": 0, "to": 1, "label": "Ea step 1"}, {"x": 2.55, "from": 2, "to": 3, "label": "Ea step 2"}, {"x": 3.3, "from": 0, "to": 4, "label": "overall change"}]}'::jsonb, null, null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-energy-diagram-process', 'ap_chemistry', 'energy_profile', 'Energy diagram for a process', 'Energy diagram for a process', 'Products below reactants means energy is released: the process is exothermic', 'Products below reactants means energy is released: the process is exothermic', 'Two energy levels joined by a falling curve. The final state sits below the initial state, so energy is released and the process is exothermic. Illustrative data.', 'course of the process', 'energy', null, true, null, '["Energy axis", "Reactants (initial state) level", "Products (final state) level", "Direction of change"]'::jsonb, '{"nodes": [{"e": 80, "label": "initial state (reactants)", "kind": "level"}, {"e": 30, "label": "final state (products)", "kind": "level"}], "arrows": [{"x": 0.5, "from": 0, "to": 1, "label": "energy released (exothermic)"}]}'::jsonb, null, null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-mass-spectrum', 'ap_chemistry', 'stick_spectrum', 'Mass spectrum of a single element', 'Mass spectrum (magnesium)', 'Magnesium: one peak per isotope, height set by natural abundance', 'Magnesium: one peak per isotope, height set by natural abundance', 'Three vertical peaks at masses 24, 25 and 26. The peak at mass 24 is by far the tallest at about 79 percent, with smaller peaks near 10 and 11 percent. Peak position identifies the isotope and peak height gives its natural abundance.', 'mass (amu)', 'relative abundance (%)', 'Isotopes differ in neutron count, not proton or electron count.', false, 'Magnesium isotope masses and abundances are taken from the PUBLISHED AP Chemistry 1.2 explainer (''Mass Spectra of Elements''), which works the same figures and cites CED 1.2.A.1-2. verify.py independently recomputes the weighted average from them and requires 24.305, so the figure is self-consistent with its source. Kept as measured data, not illustrative.', '["Peak position (x-axis)", "Peak height (y-axis)"]'::jsonb, '{"x_min": 22.6, "x_max": 27.4, "peaks": [{"x": 24, "y": 78.99, "label": "24Mg  78.99%", "exact_mass": 23.985}, {"x": 25, "y": 10.0, "label": "25Mg  10.00%", "exact_mass": 24.986}, {"x": 26, "y": 11.01, "label": "26Mg  11.01%", "exact_mass": 25.983}], "expected_average_mass": 24.305}'::jsonb, null, null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-pes', 'ap_chemistry', 'stick_spectrum', 'Photoelectron spectrum', 'Photoelectron spectrum (nitrogen)', 'Nitrogen (1s2 2s2 2p3): one peak per subshell, height set by electron count', 'Nitrogen (1s2 2s2 2p3): one peak per subshell, height set by electron count', 'Three peaks on a logarithmic binding-energy axis that decreases to the right, for nitrogen (1s2 2s2 2p3). The 1s peak sits far left at about 39.6 megajoules per mole with height two, then 2s at about 2.45 with height two, then 2p at about 1.45 with height three. Peak height is proportional to the number of electrons in that subshell, and the three heights sum to nitrogen''s seven electrons. Illustrative values.', 'binding energy (MJ/mol), decreasing to the right', 'relative number of electrons', 'Electrons closer to the nucleus need more energy to remove.', true, 'Heights (2:2:3) and the binding-energy ordering are exact for nitrogen. The 1s value cross-checks against ~400 eV (~39.5 MJ/mol), but the 2s and 2p figures are standard AP teaching values that I could not trace to a primary table, so the figure is disclosed as illustrative rather than measured.', '["Peak position", "Relative peak height"]'::jsonb, '{"x_log": true, "x_reversed": true, "x_min": 0.9, "x_max": 60, "x_tick_values": [1, 2, 5, 10, 20, 50], "peaks": [{"x": 39.6, "y": 2, "label": "1s", "subshell": "1s"}, {"x": 2.45, "y": 2, "label": "2s", "subshell": "2s"}, {"x": 1.45, "y": 3, "label": "2p", "subshell": "2p"}], "atomic_number": 7}'::jsonb, null, null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-pe-internuclear', 'ap_chemistry', 'pe_vs_distance', 'Potential energy vs. internuclear distance', 'Potential energy vs. distance', 'The minimum gives the bond length; the well depth gives the bond energy', 'The minimum gives the bond length; the well depth gives the bond energy', 'Potential energy against the distance between two nuclei, for a single and a double bond. Each curve rises steeply at short distance, passes through a minimum, and approaches zero at large separation. The double-bond curve has its minimum at a shorter distance and a deeper well than the single bond. Illustrative data.', 'internuclear distance (pm)', 'potential energy (kJ/mol)', 'Higher bond order: shorter bond, deeper well.', true, null, '["Vertical axis: potential energy", "Horizontal axis: internuclear distance", "Lowest point of the curve", "Depth of the energy well", "Effect of bond order"]'::jsonb, '{"r_min": 40, "r_max": 300, "re_label": "equilibrium bond length", "well_label": "bond energy", "zero_label": "separated atoms (E = 0)", "series": [{"label": "single bond", "de": 350, "re": 154, "a": 0.0175, "style": "solid"}, {"label": "double bond", "de": 610, "re": 134, "a": 0.0205, "style": "dashed"}]}'::jsonb, null, null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-approach-equilibrium', 'ap_chemistry', 'approach_equilibrium', 'Approach to equilibrium', 'Approach to equilibrium', 'Concentrations change, then level off (figure 1 of 2)', 'Concentrations change, then level off (figure 1 of 2)', 'Concentration against time for a reactant and a product. The reactant curve falls and the product curve rises, and both flatten to constant values after which there is no net change. Illustrative data.', 'time', 'concentration', 'Flat lines mean no net change, not that the reaction has stopped.', true, null, '["Concentration or partial pressure vs. time", "Constant region"]'::jsonb, '{"t_max": 10.0, "k": 0.55, "eq_tol": 0.02, "eq_caption": "equilibrium established", "series": [{"label": "reactant", "start": 1.0, "end": 0.3, "style": "solid"}, {"label": "product", "start": 0.0, "end": 0.7, "style": "dashed"}], "conserve": true}'::jsonb, '{:.2f}', null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-titration', 'ap_chemistry', 'titration_curve', 'Titration curve', 'Titration curve', 'Weak acid with strong base: pH = pKa at the half-equivalence point', 'Weak acid with strong base: pH = pKa at the half-equivalence point', 'pH against volume of titrant for a weak acid titrated with a strong base. The curve rises slowly through a buffer region, passes through pH equal to the pKa at half the equivalence volume, then rises steeply to an equivalence point above pH 7. Illustrative data.', 'volume of titrant added (mL)', 'pH', 'pKa is read at the half-equivalence point, not the equivalence point.', true, null, '["Vertical axis", "Horizontal axis", "Equivalence point", "Half-equivalence point"]'::jsonb, '{"v_max": 50.0, "v_eq": 25.0, "pka": 4.76, "c": 0.1, "strong": false, "half_label": "half-equivalence: pH = pKa = 4.76", "eq_label": "equivalence point"}'::jsonb, null, null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected'),
  ('chem-approach-equilibrium-rate', 'ap_chemistry', 'approach_equilibrium', 'Approach to equilibrium: rates', 'Approach to equilibrium: rates', 'Forward and reverse rates converge and become equal (figure 2 of 2)', 'Forward and reverse rates converge and become equal (figure 2 of 2)', 'Forward and reverse reaction rates against time. The forward rate falls and the reverse rate rises until the two meet at a common value and stay there. Equal rates, not zero rates, is what equilibrium means. Illustrative data.', 'time', 'rate', 'Equal rates, not zero rates: both processes continue.', true, null, '["Rate vs. time", "Constant region"]'::jsonb, '{"t_max": 10.0, "k": 0.55, "eq_tol": 0.02, "conserve": false, "eq_caption": "rates equal: equilibrium", "series": [{"label": "forward rate", "start": 0.9, "end": 0.38, "style": "solid"}, {"label": "reverse rate", "start": 0.0, "end": 0.38, "style": "dashed"}]}'::jsonb, '{:.2f}', null, 'published', 'cramapple-authored; TASK-0006 Lane A pilot 2026-10-10; property-tested; reviewed by openai/gpt-6.1-sol + google/gemini-3.5-flash with 5/5 planted controls rejected')
on conflict (figure_id) do nothing;

update app.figures set published_at = now() where status = 'published' and published_at is null;

insert into app.figure_uses (figure_id, reference_entry_id, role)
select p.figure_id, e.reference_entry_id, 'primary'
from (values
  ('chem-mb-energy', 'Maxwell-Boltzmann energy distribution'),
  ('chem-energy-profile-single', 'Single-step reaction energy profile'),
  ('chem-energy-profile-multistep', 'Multistep reaction energy profile'),
  ('chem-energy-diagram-process', 'Energy diagram for a physical or chemical process'),
  ('chem-mass-spectrum', 'Mass spectrum of a single element'),
  ('chem-pes', 'Photoelectron spectrum (PES)'),
  ('chem-pe-internuclear', 'Potential energy vs. internuclear distance graph'),
  ('chem-approach-equilibrium', 'Graphs showing the approach to equilibrium'),
  ('chem-titration', 'Titration curve (pH vs. volume of titrant)'),
  ('chem-approach-equilibrium-rate', 'Graphs showing the approach to equilibrium')
) as p(figure_id, entry_title)
join app.unit_reference_entries e
  on e.subject_key = 'ap_chemistry' and e.kind = 'diagram' and e.title = p.entry_title
on conflict do nothing;

-- Every figure must have landed somewhere; a silent zero would ship dead rows.
do $$
declare unattached text[];
begin
  select array_agg(f.figure_id) into unattached
  from app.figures f
  where f.subject_key = 'ap_chemistry'
    and not exists (select 1 from app.figure_uses u where u.figure_id = f.figure_id);
  if unattached is not null then
    raise exception 'figures with no use: %', unattached;
  end if;
end $$;

commit;
